// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint value) public {
        // Ensure target is not the contract itself and value is reasonable
        vm.assume(target != address(c));
        vm.assume(value > 0);

        // Fund the contract so it can send
        vm.deal(address(c), value);

        // Record balance of target before call
        uint balanceBefore = target.balance;

        // Call sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendMoney.selector, target, value));

        // Assert that the call succeeded and target received the specified value
        uint balanceAfter = target.balance;
        assertTrue(success && (balanceAfter - balanceBefore == value), "sendMoney did not transfer correct amount");
    }
}

